head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[Workflow > P > id]<br/>Workflow 모듈의 ID 를 설정합니다.",
    "validation" : [
        "동일 Scope 에서 Workflow 모듈을 구별할 수 있는 유일값을 설정할 수 있어야 합니다.",
        "속성명이나 메소드명과 같은 예약어를 설정할 경우 오류가 발생할 수 있습니다."
    ]
}

// 예약어 ID 로 인한 오류 발생 여부 실측용 카운터 (페이지 로드 전 구간부터 수집)
scwin.gVar = { "errCount" : 0, "lastRunId" : "" };
window.addEventListener("error", function () {
    scwin.gVar.errCount = scwin.gVar.errCount + 1;
});



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// workflow 의 function step - 실제로 실행된 Workflow 객체의 id 를 기록
scwin.wf_step_run = function (rtnVal, workflowObj) {
    scwin.gVar.lastRunId = workflowObj ? workflowObj.id : "";
};



// (1) 서로 다른 id 로 선언한 Workflow 가 id 로 구별되어 각각 실행되는지 확인
scwin.btn_checkUniqueId_onclick = async function () {
    scwin.gVar.lastRunId = "";
    await $p.executeWorkflow("wf_id_a");
    var ranA = scwin.gVar.lastRunId;

    scwin.gVar.lastRunId = "";
    await $p.executeWorkflow("wf_id_b");
    var ranB = scwin.gVar.lastRunId;

    wf_body_bottom.getObj("scwin").setReturnValue("[유일값 ID] wf_id_a 실행 시 동작한 Workflow 의 id : " + ranA + " / wf_id_b 실행 시 동작한 Workflow 의 id : " + ranB);
};

// (2) 예약어(style) 를 id 로 설정한 Workflow 의 오류 발생 여부 확인
scwin.btn_checkReservedId_onclick = function () {
    var wfReserved = $p.getWorkflow("style");
    var reservedId = wfReserved ? wfReserved.id : "null";

    wf_body_bottom.getObj("scwin").setReturnValue("[예약어 ID] getWorkflow(style) 반환 객체의 id : " + reservedId + " / 페이지 로드 이후 수집된 오류 건수 : " + scwin.gVar.errCount);
};
